#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.20194721999999998, 0.0003443999999999947, 0.018016815], 'basis': [[-0.0, 0.8858637803302598, 0.46394543073402666], [0.0012906765230830972, -0.46394504430307193, 0.8858630424736849], [0.9999991670767095, 0.0005988034754400834, -0.0011433635839219081]], 'axis': [0.46394543073402666, 0.8858630424736849, -0.0011433635839219081], 'zmin': -0.21849374522990123, 'zmax': 0.2184937440496349, 'profiles': [{'outer': [[-0.040741025767511325, -0.01788594306657267], [-0.040439031147554004, -0.015586366243637767], [-0.03955819025517467, -0.011377594239040669], [-0.039346992982387224, -0.010780350423280956], [-0.04015848132645772, -0.0069026825790127104], [-0.040473459739220764, -0.004605803789705424], [-0.0407869294781243, -0.00011708939711455549], [-0.04047346973921243, 0.004376403146327412], [-0.040171475132161884, 0.006675975750074933], [-0.03929063422687578, 0.010884743115221591], [-0.037879743213193776, 0.014891167189559991], [-0.03714426385882474, 0.016761411859224265], [-0.03556147018390313, 0.020001369891970582], [-0.03292386623077152, 0.024094138431262745], [-0.031216377269733732, 0.02631504105132291], [-0.028697117495382268, 0.029051841687724168], [-0.027163617454835223, 0.030521141661310754], [-0.025109650483469588, 0.03223951173810676], [-0.02269745957240212, 0.033998299901179106], [-0.01988220968851527, 0.03573269808844824], [-0.016634038667182653, 0.03736932893958761], [-0.012952852103670762, 0.03880989379036523], [-0.00888838210838657, 0.03994967750947309], [-0.004525114154520856, 0.0406814801661896], [7.5840035520794745e-06, 0.04093624149486301], [0.004535608298586097, 0.04068690576280363], [0.008899713075482317, 0.0399603290915626], [0.012965506308306887, 0.03882543152366261], [0.016648343611122895, 0.037389258562366634], [0.019898407177254832, 0.03575651887992351], [0.02271565260192755, 0.034025493453229784], [0.02512986767083079, 0.032269621937152784], [0.027185827276208732, 0.03055368632481115], [0.028717354682726813, 0.029086221701840893], [0.031243440705985826, 0.026352468814467893], [0.03294927890190598, 0.0241336101082745], [0.03559584054746611, 0.020043979172429758], [0.03717760423670878, 0.01680596924103652], [0.03792486364733106, 0.014936585865323981], [0.03927803366004298, 0.011110391478661798], [0.040158591313459335, 0.0069026607084180765], [0.04047357616669823, 0.004603466833339741], [0.04078704590560177, 0.00011034969776063108], [0.040473586166689904, -0.004378740102693108], [0.040171575119171826, -0.006675997626657574], [0.03929074423969092, -0.010884756547441502], [0.039022269521946415, -0.011660628288871586], [0.03983375199131964, -0.015538272006160892], [0.040148736857465304, -0.01783747937932749], [0.04060309510256607, -0.024488842816131385], [0.04028962536366253, -0.028977923763935338], [0.03998762430322936, -0.03127518550109916], [0.039106783423756786, -0.035483953286508906], [0.03775318567809372, -0.039311772715641666], [0.037017696323733015, -0.04118202624993181], [0.035434912674616605, -0.04442196697967754], [0.03279729872149333, -0.04851474438359551], [0.031089799747557108, -0.05073564237019332], [0.028570549986104074, -0.053472438781419135], [0.027037049932650263, -0.05494174297419311], [0.024983082974191398, -0.05666011769043958], [0.022570892063123925, -0.0584188969948741], [0.019755652166321983, -0.06015329053670473], [0.016507461132099263, -0.06178992561900754], [0.012826284607299333, -0.06323052209942406], [0.008761814586201611, -0.06437028768099326], [0.004398546632335898, -0.06510208147907195], [-0.000129181542783429, -0.06535683519224164], [-0.004662185820762725, -0.06510752479894961], [-0.009026280597667274, -0.06438094812172057], [-0.013092073804678313, -0.06324604211544585], [-0.016774921146206285, -0.06180986410042436], [-0.02002499469942313, -0.06017713792205752], [-0.022842230111197417, -0.05844611712882624], [-0.02525645518009232, -0.05669022790146165], [-0.02731241479837703, -0.05497431422558298], [-0.028843932191996675, -0.053506845377437315], [-0.03137002822815412, -0.05077307013932631], [-0.03307585641117584, -0.048554216066595324], [-0.035722418056735976, -0.044464611706664006], [-0.03730418177179217, -0.041226565920456454], [-0.038051451182406125, -0.039357200268007576], [-0.03940462118221128, -0.03553099280352021], [-0.04028517883562763, -0.03132327975055211], [-0.04060015726129745, -0.029026396321794386], [-0.04105449550641486, -0.022379453333278246]], 'holes': []}], 'simplify_tolerance': 2.1258615337420932e-05, 'sketch_entity_count': 89}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
